CREATE POLICY "agent update own profile photo" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'candidate-photos' AND name = 'candidate-drafts/' || auth.uid()::text || '/agent-profile.jpg' AND public.has_role_text(auth.uid(), 'agent') AND public.is_active_account(auth.uid())) WITH CHECK (bucket_id = 'candidate-photos' AND name = 'candidate-drafts/' || auth.uid()::text || '/agent-profile.jpg' AND public.has_role_text(auth.uid(), 'agent') AND public.is_active_account(auth.uid()));
CREATE POLICY "workflow read linked agent avatar" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'candidate-photos' AND (storage.foldername(name))[1] = 'candidate-drafts' AND name = 'candidate-drafts/' || (storage.foldername(name))[2] || '/agent-profile.jpg' AND public.is_active_account(auth.uid()) AND EXISTS (SELECT 1 FROM public.job_submissions s WHERE s.submitted_by::text = (storage.foldername(name))[2]));